local config = {
  ui_story_40110001_1_dialog_content = "*Ahem* All preparations are complete. We can begin now.",
  ui_story_40110001_2_dialog_content = "Esteemed friends, for our upcoming and all-important poetry recital, as well as for those who are important for us—",
  ui_story_40110001_3_dialog_content = "We'll hold a poetry contest here atop our beloved Colossus!",
  ui_story_40110001_4_dialog_content = "We have many contestants joining us today!",
  ui_story_40110001_5_dialog_content = "Here to illuminate our lives, the shining light of the Academy, please welcome Lumopolis' own... Keating!",
  ui_story_40110001_6_dialog_content = "Next, a nun who also hails from Lumopolis! Let's hear it for the graceful, the gentle me... Uriah!",
  ui_story_40110001_7_dialog_content = "Last, but certainly not least, is a famous Lumopolis musician, known and loved by all! Let's hear it for... Chloe!",
  ui_story_40110001_8_dialog_content = "... And as a friendly word of caution, I advise everyone to do their best not to make her cry.",
  ui_story_40110001_9_dialog_content = "And now, allow me to introduce the judge of our festivities... PlayerName!",
  ui_story_40110001_10_dialog_content = "E-Eh? But everybody already knows me... Do I really need an introduction?",
  ui_story_40110001_11_dialog_content = "Of course. It's part of tonight's events, after all.",
  ui_story_40110001_12_dialog_content = "Okay...",
  ui_story_40110001_13_dialog_content = "A master Colossus pilot with at least 17 years of experience, he also has the power to read people's minds! A young prodigy, to be sure, or perhaps some sort of monster...",
  ui_story_40110001_14_dialog_content = "W-What? No! I wasn't able to pilot the Colossus UNTIL I was 17! Also, I've never been able to read minds!",
  ui_story_40110001_15_dialog_content = "For reasons unknown to all, he enjoys the profound admiration of many...",
  ui_story_40110001_16_dialog_content = "Although, it is possible that he became a Colossus pilot precisely to forcibly recruit others and demand their admiration...",
  ui_story_40110001_17_dialog_content = "Who the hell wrote this introduction?! Was it Uriah...?",
  ui_story_40110001_18_dialog_content = "No wait, it was ALL of you! See? Keating has been laughing over there this whole time!",
  ui_story_40110001_19_dialog_content = "Looks like the cat's out of the bag. Well done, Navigator.",
  ui_story_40110001_20_dialog_content = "But Pierre and I have been laughing, too!",
  ui_story_40110001_21_dialog_content = "You're pretty willing to accuse people after finding such a trivial clue, huh?",
  ui_story_40110001_22_dialog_content = "A gentleman, through and through.",
  ui_story_40110001_23_dialog_content = "S-Sorry, I just got a little worked up. I shouldn't be so quick to suspect you guys...",
  ui_story_40110001_24_dialog_content = "Although we did write up that introduction...",
  ui_story_40110001_25_dialog_content = "Wait, now you're confessing?! So I was right!!",
  ui_story_40110001_26_dialog_content = "*Ahem* I apologize for the interruption, everyone, but please allow me to introduce our next judge... Miss Vice!",
  ui_story_40110001_27_dialog_content = "Ahaha... Hello, everyone. I kind of got dragged into this at the last minute...",
  ui_story_40110001_28_dialog_content = "What's with all this... What are we getting ourselves into?",
  ui_story_40110001_29_dialog_content = "The opening remarks were pretty clear...",
  ui_story_40110001_30_dialog_content = "Yet you still don't understand...",
  ui_story_40110001_31_dialog_content = "Then let's explain it once more.",
  ui_story_40110001_32_dialog_content = "We will be reciting poetry for you.",
  ui_story_40110001_33_dialog_content = "About your story.",
  ui_story_40110001_34_dialog_content = "And about your victories.",
  ui_story_40110001_35_dialog_content = "After listening, you will share your thoughts on our poetry with us.",
  ui_story_40110001_36_dialog_content = "And then choose the one you liked the most.",
  ui_story_40110001_37_dialog_content = "Simple, right?",
  ui_story_40110001_38_dialog_content = "Uriah... Is it really as simple as they say? Why is everyone being so nice to me all of a sudden?",
  ui_story_40110001_39_dialog_content = "Em... I could answer that, but we don't have much time left... So let's just get started!",
  ui_story_40110001_40_dialog_content = "Now then, our first contestant... Keating! Please take the stage!",
  ui_story_40110001_41_dialog_content = "They made such a splashy intro, and now they want to hurry it up...",
  ui_story_40110001_42_dialog_content = "...",
  ui_story_40110001_43_dialog_content = "...",
  ui_story_40110001_44_dialog_content = "...",
  ui_story_40110001_45_dialog_content = "Aren't you guys in a hurry to get started? Why is nobody talking?!",
  ui_story_40110001_46_dialog_content = "Ahem. Please share your first impressions of the contestants among yourselves, judges.",
  ui_story_40110001_47_dialog_content = "It's an unwritten rule of the poetry contest.",
  ui_story_40110001_48_dialog_content = "I see. It's such a rare opportunity to see these kids being so serious.",
  ui_story_40110001_49_dialog_content = "Really? They don't look any different from usual.",
  ui_story_40110001_50_dialog_content = "Don't say that! This is a sacred event! Or at least I think so...",
  ui_story_40110001_51_dialog_content = "Dearest PlayerName, I dedicate this poem to you.",
  ui_story_40110001_52_dialog_content = "And now they're starting out of the blue?",
  ui_story_40110001_53_dialog_content = "\"The days grow cold,\"",
  ui_story_40110001_54_dialog_content = "\"The sun grows bleak,\"",
  ui_story_40110001_55_dialog_content = "\"I raise my glass...\"",
  ui_story_40110001_56_dialog_content = "\"And look through the water inside.\"",
  ui_story_40110001_57_dialog_content = "\"I think of the days we spent together...\"",
  ui_story_40110001_58_dialog_content = "\"But feelings threaten to tear me asunder.\"",
  ui_story_40110001_59_dialog_content = "\"You've gone to someplace far, far away...\"",
  ui_story_40110001_60_dialog_content = "\"And the silent earth keeps my joy at bay...\"",
  ui_story_40110001_61_dialog_content = "\"My only wish is to see you once more,\"",
  ui_story_40110001_62_dialog_content = "\"But all I can see are weeds outside your door.\"",
  ui_story_40110001_63_dialog_content = "Splendid! Now let's hear what our judges have to say!",
  ui_story_40110001_64_dialog_content = "Eh? It's over already? Wasn't that too quick?",
  ui_story_40110001_65_dialog_content = "Y-You go first, Vice! Hmm? Where did she go?",
  ui_story_40110001_66_dialog_content = "My apologies, but Vice had a small matter to attend to and took her leave moments ago.",
  ui_story_40110001_67_dialog_content = "Now then, please share your thoughts with us on their poem, PlayerName!",
  ui_story_40110001_68_dialog_content = "She had to leave because of a \"small matter\"?! Give me a break, guys...",
  ui_story_40110001_69_dialog_content = "Please share your thoughts with us, PlayerName!",
  ui_story_40110001_70_dialog_content = "She's just ignoring me at this point, isn't she...",
  ui_story_40110001_71_dialog_content = "Please share your...",
  ui_story_40110001_72_dialog_content = "I get it, already! Jeez!",
  ui_story_40110001_73_option_content = "I think it was pretty good...",
  ui_story_40110001_74_dialog_content = "At least, it was way nicer than the things you usually say about me or my hair.",
  ui_story_40110001_75_dialog_content = "I know you guys are just messing with me, but the \"weeds outside your door\" part was actually pretty poetic.",
  ui_story_40110001_76_option_content = "It was pretty bad...",
  ui_story_40110001_77_dialog_content = "All I could think after hearing your poem was, \"I have no idea what they're talking about...\"",
  ui_story_40110001_78_dialog_content = "I mean the style is inconsistent, the words are too simple, and the meaning behind them is... unclear.",
  ui_story_40110001_79_dialog_content = "Is Uriah teaching you guys some new way of messing with me or something?",
  ui_story_40110001_80_dialog_content = "Dearest PlayerName,",
  ui_story_40110001_81_dialog_content = "The style may be inconsistent...",
  ui_story_40110001_82_dialog_content = "But our feelings are clear.",
  ui_story_40110001_83_dialog_content = "Yet not only are you incapable of understanding our poem...",
  ui_story_40110001_84_dialog_content = "You also have the nerve to criticize it.",
  ui_story_40110001_85_dialog_content = "You guys were the ones who asked me to judge in the first place!!!",
  ui_story_40110001_86_dialog_content = "Um, p-please don't be angry. Would you like some water?",
  ui_story_40110001_87_dialog_content = "No thanks, I'm not really mad. I just got a little worked up, that's all.",
  ui_story_40110001_88_dialog_content = "Wonderful! Then would you like some sweets? Everyone feels better after eating something sweet...",
  ui_story_40110001_89_dialog_content = "N-No really, I'm not mad at all... I promise...",
  ui_story_40110001_90_dialog_content = "Now then, please allow me to offer you...",
  ui_story_40110001_91_dialog_content = "Our sincerest condolences.",
  ui_story_40110001_92_dialog_content = "Today, we would like to commemorate our dearest friend.",
  ui_story_40110001_93_dialog_content = "W-Wait a second! Are you sure this is still for me?!",
  ui_story_40110001_94_dialog_content = "Yes.",
  ui_story_40110001_95_dialog_content = "Sorry, I don't really know what to say...",
  ui_story_40110001_96_dialog_content = "Don't worry. It is perfectly alright to sit in quiet contemplation after hearing this next poem.",
  ui_story_40110001_97_dialog_content = "N-No, it's just that, well... Am I supposed to be dead?",
  ui_story_40110001_98_dialog_content = "Obviously. Part of my job is to preside over funerals, after all.",
  ui_story_40110001_99_dialog_content = "So, just to be clear... Why exactly are we holding this poetry contest today?",
  ui_story_40110001_100_dialog_content = "It's a practice for the poetry recital! And also to see your reaction.",
  ui_story_40110001_101_dialog_content = "My reaction? Wait, are you practicing for my funeral?!",
  ui_story_40110001_102_dialog_content = "... It's a practice for the poetry recital!",
  ui_story_40110001_103_dialog_content = "You're ignoring me again! Also...",
  ui_story_40110001_104_dialog_content = "Is she crying over there?!",
  ui_story_40110001_105_dialog_content = "*Sniffs* I'm sorry... It's just, when I think of you... I...",
  ui_story_40110001_106_dialog_content = "Knock that off, I'm not dead! I'm not!!",
  ui_story_40110001_107_dialog_content = "My apologies, but due to an unforeseen interruption, today's contest has been slightly delayed.",
  ui_story_40110001_108_dialog_content = "Without further ado, let us continue once again!",
  ui_story_40110001_109_dialog_content = "Due to concerns that the interruption will affect our third contestant's performance, we are slightly adjusting the order. Please welcome Miss Chloe to the stage!",
  ui_story_40110001_110_dialog_content = "Chloe, you...",
  ui_story_40110001_111_dialog_content = "I-Is everything okay? Do you still want to continue...?",
  ui_story_40110001_112_dialog_content = "Er, I... Wait, shouldn't I be asking you that?!",
  ui_story_40110001_113_dialog_content = "Well, it's just that... Given your current state of mind...",
  ui_story_40110001_114_dialog_content = "I'm okay, I swear!! Also, are you sure you're okay? You were crying just a minute ago!",
  ui_story_40110001_115_dialog_content = "I-It's fine... I can do this...",
  ui_story_40110001_116_dialog_content = "This is how people usually are...",
  ui_story_40110001_117_dialog_content = "\"This is the just way I am!\"",
  ui_story_40110001_118_dialog_content = "(Why is she singing all of a sudden?! It's not bad, though...)",
  ui_story_40110001_119_dialog_content = "\"And I know, yes I know, that we have to move on! But our memories are not so easily foregone!\"",
  ui_story_40110001_120_dialog_content = "\"Maybe our happiness was doomed from the beginning...\"",
  ui_story_40110001_121_dialog_content = "\"But the world doesn't care, as it keeps on spinning...\"",
  ui_story_40110001_122_dialog_content = "I...",
  ui_story_40110001_123_dialog_content = "Oh Chloe, you're crying again...",
  ui_story_40110001_124_dialog_content = "Wow, not even we would make her cry like this...",
  ui_story_40110001_125_dialog_content = "You really are something else, Navigator.",
  ui_story_40110001_126_dialog_content = "I hope you're proud of yourself.",
  ui_story_40110001_127_dialog_content = "W-What?! Why are you looking at me? I didn't do anything!!",
  ui_story_40110001_128_dialog_content = "I'm sorry... It's just, when I think of you... I...",
  ui_story_40110001_129_dialog_content = "\"When you think of me\"? I told you I'm fine! Please don't cry!",
  ui_story_40110001_130_dialog_content = "I'm back! I'm finished with that thing you asked for, Miss Uriah!",
  ui_story_40110001_131_dialog_content = "Huh? Wait, Vice... You left earlier because Uriah asked you to do something? What was it?!",
  ui_story_40110001_132_dialog_content = "Well, Navigator, you see... We're going to land soon.",
  ui_story_40110001_133_dialog_content = "Land? Where are we landing? Why didn't anyone tell me anything?!",
  ui_story_40110001_134_dialog_content = "Somewhere on the outskirts of Umbraton... I think? Anyways, we can't stay on the ground for too long, or we could be in serious trouble.",
  ui_story_40110001_135_dialog_content = "Huh?! W-What the hell is going on around here?!",
  ui_story_40110001_136_dialog_content = "My apologies, Navigator... But the choir recital will begin shortly, and we are running short on time.",
  ui_story_40110001_137_dialog_content = "What exactly are you up to? Where are we going? Someone needs to fill me in right now!",
  ui_story_40110001_138_dialog_content = "Quickly, Navigator! Hold these flowers!",
  ui_story_40110001_139_dialog_content = "Huh? Where'd you get these white flowers?!",
  ui_story_40110001_140_dialog_content = "W-Wait up! Where are you all going?!",
  ui_story_40110001_141_dialog_content = "*Sighs*... Do I even want to follow...?",
  ui_story_40110001_142_dialog_content = "What are we doing in this giant, empty field? There isn't anyone around... No wait, who are those people?",
  ui_story_40110001_143_dialog_content = "Most of them look like they're from Umbraton... Hang on, there are people from Lumopolis, too?",
  ui_story_40110001_144_dialog_content = "I...",
  ui_story_40110001_145_option_content = "I think I should stay.",
  ui_story_40110001_146_dialog_content = "<color=#e8d9bb>Someone gently pushes me on my back.</color>",
  ui_story_40110001_147_dialog_content = "Vice...",
  ui_story_40110001_148_dialog_content = "Go ahead, leave the Colossus to me. I'll be back to pick you up in a bit.",
  ui_story_40110001_149_dialog_content = "But I still don't know what's going on! Why should I go with them...?",
  ui_story_40110001_150_dialog_content = "... Look, they're already so far ahead now.",
  ui_story_40110001_151_dialog_content = "Just now, during the poetry contest... You were laughing one second and angry the next, but you were speaking and interacting with everyone all the same.",
  ui_story_40110001_152_dialog_content = "The first time I saw you, I never thought you could show this much emotion.",
  ui_story_40110001_153_dialog_content = "It's just like what Keating said: Everyone admires you more than you know, now go!",
  ui_story_40110001_154_dialog_content = "But...",
  ui_story_40110001_155_dialog_content = "Everyone's waiting for those flowers in your hands, so don't keep them waiting too long.",
  ui_story_40110001_156_dialog_content = "... I understand. I'll be going, then.",
  ui_story_40110001_157_option_content = "I should go catch up to them.",
  ui_story_40110001_158_dialog_content = "They're walking way too fast! Can't they see I'm carrying this giant bouquet...?",
  ui_story_40110001_159_dialog_content = "...",
  ui_story_40110001_160_dialog_content = "Why are there armed guards suddenly rushing at me?!",
  ui_story_40110001_161_dialog_content = "Halt!",
  ui_story_40110001_162_dialog_content = "*Ahem* W-What's the problem? I'll have you know, I was invited here by important people in Lumopolis...",
  ui_story_40110001_163_dialog_content = "See that crowd wearing white over there? I'm with them.",
  ui_story_40110001_164_dialog_content = "If you don't believe me, go ask one of them! But please, just put down your weapons!",
  ui_story_40110001_165_dialog_content = "You... Why are you so afraid?",
  ui_story_40110001_166_dialog_content = "W-Who's afraid? I-I-I'm perfectly calm!",
  ui_story_40110001_167_dialog_content = "You're trembling so hard that you're dropping all your flowers...",
  ui_story_40110001_168_dialog_content = "A-Ah, that's because I'm carrying too many!",
  ui_story_40110001_169_dialog_content = "I see. Let me help you pick them up.",
  ui_story_40110001_170_dialog_content = "Eh? O-Okay... Thanks.",
  ui_story_40110001_171_dialog_content = "<color=#e8d9bb>The guard picked up a large bunch of flowers before running off towards a large group of people.</color>",
  ui_story_40110001_172_dialog_content = "<color=#e8d9bb>Uriah stood at the center of the crowd, apparently speaking to the people around her...</color>",
  ui_story_40110001_173_dialog_content = "Thank you all for coming to our poetry recital today.",
  ui_story_40110001_174_dialog_content = "Today, we would like to express our sincerest grief and mourning.",
  ui_story_40110001_175_dialog_content = "Today, we would like to commemorate our dearest friend.",
  ui_story_40110001_176_dialog_content = "To our friend.",
  ui_story_40110001_177_dialog_content = "Once, a great and devastating war befell this land, and many were lost to the Eclipsite menace...",
  ui_story_40110001_178_dialog_content = "Some saw them as the enemy, others as a blind and destructive force of nature...",
  ui_story_40110001_179_dialog_content = "<color=#e8d9bb>After saying this, Uriah began handing out white flowers to every person in the crowd.</color>",
  ui_story_40110001_180_dialog_content = "<color=#e8d9bb>And Chloe began singing the song, \"White Flower.\"</color>",
  ui_story_40110001_181_dialog_content = "<color=#e8d9bb>Keating, rather than stirring up trouble as usual, was quietly consoling a crying guest.</color>",
  ui_story_40110001_182_dialog_content = "<color=#e8d9bb>It was a small funeral, and everything they were doing before was in preparation for it.</color>",
  ui_story_40110001_183_dialog_content = "So the poetry contest... was to pick which poem would be recited here...",
  ui_story_40110001_184_dialog_content = "I'm still not sure what the idea behind the contest really was...",
  ui_story_40110001_185_option_content = "Go ask Uriah.",
  ui_story_40110001_186_dialog_content = "Navigator, do you remember the white flower I gave you before?",
  ui_story_40110001_187_dialog_content = "Yes.",
  ui_story_40110001_188_dialog_content = "That day, you asked me about my story, but the truth is I have no story...",
  ui_story_40110001_189_dialog_content = "I'm nothing more than an ordinary person, one who survived by deserting the front lines long ago.",
  ui_story_40110001_190_dialog_content = "My family, my friends... All of them alive and well.",
  ui_story_40110001_191_dialog_content = "A person once asked me, \"What could you possibly know about the pain of losing someone?\"",
  ui_story_40110001_192_dialog_content = "Was that during a funeral you were presiding over?",
  ui_story_40110001_193_dialog_content = "Yes... Perhaps my approach failed to take your feelings into account, and for that I apologize.",
  ui_story_40110001_194_dialog_content = "But when Keating said she wanted to invite you to the poetry recital, I wholeheartedly agreed.",
  ui_story_40110001_195_dialog_content = "Navigator... Despite her constant tears, Chloe truly wishes that you would smile more.",
  ui_story_40110001_196_dialog_content = "Miss Vice agrees, which is why she chose to lend us her aid, as well.",
  ui_story_40110001_197_dialog_content = "Ah... I think I understand now. So basically, you are hoping that I can accept this \"poetry recital\", right?",
  ui_story_40110001_198_dialog_content = "Yes. I believe you... like everyone else, have those whom you wish to commemorate.",
  ui_story_40110001_199_dialog_content = "But what should I do? If I have people that I want to remember...",
  ui_story_40110001_200_dialog_content = "You can do what everyone else does and lay flowers in a field for the wind to carry away.",
  ui_story_40110001_201_dialog_content = "Yes.",
  ui_story_40110001_202_option_content = "Go ask Chloe.",
  ui_story_40110001_203_dialog_content = "Are you alright? Your eyes were full of tears just now... Is the wind here stinging your eyes?",
  ui_story_40110001_204_dialog_content = "I'm fine now, thank you for checking on me.",
  ui_story_40110001_205_dialog_content = "This poetry recital... It's nothing like what I expected it to be.",
  ui_story_40110001_206_dialog_content = "Yes... There's no grand stage, no flashing lights...",
  ui_story_40110001_207_dialog_content = "Just dirt, grass, and wind all around us... But even so, they were willing to attend.",
  ui_story_40110001_208_dialog_content = "\"And I know, yes I know, that we have to move on! But our memories are not so easily foregone!\"",
  ui_story_40110001_209_dialog_content = "\"Maybe our happiness was doomed from the beginning...\"",
  ui_story_40110001_210_dialog_content = "\"But the world doesn't care, as it keeps on spinning...\"",
  ui_story_40110001_211_dialog_content = "\"I dream of a promenade by a distant lake...\"",
  ui_story_40110001_212_dialog_content = "\"Of birds singing songs in the setting sun's wake...\"",
  ui_story_40110001_213_dialog_content = "\"And I know, yes I know, that we have to move on! But our memories are not so easily foregone!\"",
  ui_story_40110001_214_dialog_content = "\"Will our memories fade from that field or our hearts?\"",
  ui_story_40110001_215_dialog_content = "\"But there's still so much pain that has yet to depart...\"",
  ui_story_40110001_216_dialog_content = "\"All I can do is lay flowers on this plain... And hope the wind carries them away with my pain.\"",
  ui_story_40110001_217_option_content = "Go ask Keating.",
  ui_story_40110001_218_dialog_content = "Looks like Chloe is finished with her song.",
  ui_story_40110001_219_dialog_content = "What did you think?",
  ui_story_40110001_220_dialog_content = "Hmm? Why ask me that, all of a sudden?",
  ui_story_40110001_221_dialog_content = "You looked like you were enjoying it back on the Colossus.",
  ui_story_40110001_222_dialog_content = "Her song is probably your favorite, isn't it?",
  ui_story_40110001_223_dialog_content = "Huh? Oh, you're still talking about the poetry contest.",
  ui_story_40110001_224_dialog_content = "I thought you were just teasing me again.",
  ui_story_40110001_225_dialog_content = "Still unsure? Or are you just not willing to think about it?",
  ui_story_40110001_226_dialog_content = "Cut it out! This whole thing was your idea, wasn't it? Tell me what's going on.",
  ui_story_40110001_227_dialog_content = "Not before you tell us your favorite!",
  ui_story_40110001_228_dialog_content = "Don't try to dodge the question.",
  ui_story_40110001_229_dialog_content = "Dear PlayerName.",
  ui_story_40110001_230_dialog_content = "To seek the truth is normal and fine,",
  ui_story_40110001_231_dialog_content = "But first you must pass a test of the mind.",
  ui_story_40110001_232_dialog_content = "And only then will the answer be thine.",
  ui_story_40110001_233_dialog_content = "\"Some lose their lovers,\"",
  ui_story_40110001_234_dialog_content = "\"Some lose their friends.\"",
  ui_story_40110001_235_dialog_content = "\"All that they want is to see them again,\"",
  ui_story_40110001_236_dialog_content = "Now what do you think the next line should be?",
  ui_story_40110001_237_dialog_content = "\"But all I can see are weeds outside your door.\"",
  ui_story_40110001_238_dialog_content = "I'm sorry, I think I finally understand...",
  ui_story_40110001_239_dialog_content = "You guys weren't mocking anyone or joking around... You prepared these poems with all your hearts.",
  ui_story_40110001_240_dialog_content = "Yes.",
  ui_story_40110001_241_dialog_content = "Dear PlayerName.",
  ui_story_40110001_242_dialog_content = "Here it is, the long-awaited truth!",
  ui_story_40110001_243_dialog_content = "Did you really believe all of this was for you?",
  ui_story_40110001_244_dialog_content = "It was actually a last-minute call to let you participate.",
  ui_story_40110001_245_dialog_content = "And we just needed a ride to the venue.",
  ui_story_40110001_246_dialog_content = "You guys... I guess Keating's still the same as ever...",
  ui_story_40110001_247_dialog_content = "<color=#e8d9bb>The wind suddenly picked up, blowing them away as the crowd huddled together.</color>",
  ui_story_40110001_248_dialog_content = "That should be Vice coming to pick us up. Shall we go back together?",
  ui_story_40110001_249_dialog_content = "And what if you are?",
